use super::*;
use std::{fs,path::PathBuf,sync::atomic::{AtomicUsize,Ordering},time::{Duration,SystemTime}};
fn fixture()->PathBuf{let p=std::env::temp_dir().join(format!("nearly-held-unit-{}-{}",std::process::id(),getrandom::u64().unwrap()));fs::create_dir_all(p.join("dir")).unwrap();fs::write(p.join("owned-marker"),b"generated held unit").unwrap();fs::write(p.join("dir/item"),b"oldbytes").unwrap();p.canonicalize().unwrap()}
#[test]fn held_policy_is_default_without_diagnostic_features_or_fixture_markers(){assert!(enabled("example.invalid",Path::new("not-an-owned-fixture")).unwrap());}

#[test]fn held_input_stays_fresh_for_inplace_change_and_byte_count(){let root=fixture();let p=root.join("dir/item");let f=crate::sftp::compatible::open_held_source_checked(&root,Path::new("dir/item"),&|_,_|Ok(())).unwrap();let before=crate::source_change::Snapshot::capture(&f).unwrap();assert_eq!(before.changed_opened(&f,8).unwrap(),None);assert!(before.changed_opened(&f,7).unwrap().is_some());fs::write(&p,b"newbytes").unwrap();fs::File::options().write(true).open(&p).unwrap().set_times(fs::FileTimes::new().set_modified(SystemTime::now()+Duration::from_secs(5))).unwrap();assert!(before.changed_opened(&f,8).unwrap().is_some());drop(f);}
#[test]fn held_root_veto_is_not_cached_across_post_observations(){let root=fixture();let f=crate::sftp::compatible::open_held_source_checked(&root,Path::new("dir/item"),&|_,_|Ok(())).unwrap();let snapshot=crate::source_change::Snapshot::capture(&f).unwrap();let n=AtomicUsize::new(0);let allow=|p:&Path,d:bool|{assert!(p.as_os_str().is_empty()&&d);n.fetch_add(1,Ordering::SeqCst);Ok(())};for _ in 0..3{assert!(!changed(&snapshot,&f,8,&allow).unwrap());}assert_eq!(n.load(Ordering::SeqCst),3);assert!(changed(&snapshot,&f,8,&|_,_|Err("generated root veto".into())).unwrap());}
#[test]fn held_initial_source_rejects_root_veto_and_missing_or_directory(){let root=fixture();assert!(crate::sftp::compatible::open_held_source_checked(&root,Path::new("dir/item"),&|_,_|Err("generated veto".into())).is_err());assert!(crate::sftp::compatible::open_held_source_checked(&root,Path::new("dir/missing"),&|_,_|Ok(())).is_err());assert!(crate::sftp::compatible::open_held_source_checked(&root,Path::new("dir"),&|_,_|Ok(())).is_err());fs::rename(root.join("dir"),root.join("moved")).unwrap();}
#[test]fn held_predelete_handles_a_legitimately_removed_watch_scope(){let root=fixture();fs::remove_file(root.join("dir/item")).unwrap();fs::remove_dir(root.join("dir")).unwrap();let n=AtomicUsize::new(0);before_delete(&root,Path::new("dir"),&std::sync::atomic::AtomicBool::new(false),&crate::exclusion::Rules::compile("").unwrap(),true,&|_,_|{n.fetch_add(1,Ordering::SeqCst);Ok(())}).expect("legitimate removed scope must permit a fresh surviving-root barrier");assert_eq!(n.load(Ordering::SeqCst),2);}
#[test]fn held_predelete_stop_precedes_authority_checks(){let root=fixture();let stop=std::sync::atomic::AtomicBool::new(true);let expected=crate::file_ops::check(&stop).unwrap_err();assert_eq!(before_delete(&root,Path::new(""),&stop,&crate::exclusion::Rules::compile("").unwrap(),true,&|_,_|panic!("stop must precede root query")).unwrap_err(),expected);}
#[test]fn held_predelete_does_not_hide_a_scope_type_conflict(){let root=fixture();assert!(before_delete(&root,Path::new("dir/item"),&std::sync::atomic::AtomicBool::new(false),&crate::exclusion::Rules::compile("").unwrap(),true,&|_,_|Ok(())).unwrap_err().contains("scope changed"));assert!(before_delete(&root,Path::new("../outside"),&std::sync::atomic::AtomicBool::new(false),&crate::exclusion::Rules::compile("").unwrap(),true,&|_,_|panic!("invalid scope must precede root query")).is_err());}
